<div style="display:flex;gap:4px;flex-wrap:wrap">
  <button id="btnSingle" class="active">single slice da</button>
  <button id="btnAcc">accumulate R1 → r</button>
</div>
<div id="readout" style="font-family:ui-monospace,Consolas,monospace;font-size:11px;line-height:1.55;background:#f2f4f7;border:1px solid #dcdfe3;border-radius:4px;padding:6px 8px;white-space:pre-wrap"></div>
