  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx); g.computeVertexNormals(); return g;
}
function mat(hex) { return new THREE.MeshLambertMaterial({ color: hex, side: THREE.DoubleSide }); }
function ringPts(rad, y) {
  const a = [];
  for (let i = 0; i <= NSEG; i++) { const t = TH_A + (TH_B - TH_A) * i / NSEG; a.push(new THREE.Vector3(rad * Math.cos(t), y, rad * Math.sin(t))); }
  return a;
}
function arrowHead(color, size) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(size, size * 2.6, 14), new THREE.MeshBasicMaterial({ color }));
  m.userData.size = size; return m;
}
function aimHead(mesh, tip, dir) {
  const d = dir.clone().normalize();
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d);
  mesh.position.copy(tip).addScaledVector(d, -mesh.userData.size * 1.3);
}
function mkLine(dashed, color, width) {
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: color ?? 0x000000, dashSize: 0.1, gapSize: 0.07 })
    : new THREE.LineBasicMaterial({ color: color ?? 0x000000 });
  const l = new THREE.Line(new THREE.BufferGeometry(), m);
  l.renderOrder = 3; scene.add(l); return l;
}
function setLine(l, pts) {
  l.geometry.dispose();
  l.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (l.material.isLineDashedMaterial) l.computeLineDistances();
}

/* ── toroid body ──────────────────────────────────────────────────────── */
const innerTop = ringPts(R1, H / 2), outerTop = ringPts(R2, H / 2);
const innerBot = ringPts(R1, -H / 2), outerBot = ringPts(R2, -H / 2);

const topFace = new THREE.Mesh(quadStrip(innerTop, outerTop), mat(0xb3b3b3)); scene.add(topFace);
const botFace = new THREE.Mesh(quadStrip(innerBot, outerBot), mat(0xb0b0b0)); scene.add(botFace);
const outWall = new THREE.Mesh(quadStrip(outerTop, outerBot), mat(0x8f8f8f)); scene.add(outWall);
const inWall = new THREE.Mesh(quadStrip(innerTop, innerBot), mat(0x5a5a5a)); scene.add(inWall);

const last = NSEG;
const faceRight = new THREE.Mesh(
  quadStrip([innerTop[last], outerTop[last]], [innerBot[last], outerBot[last]]), mat(0xc4c4c4));
scene.add(faceRight);
const faceLeft = new THREE.Mesh(
  quadStrip([innerTop[0], outerTop[0]], [innerBot[0], outerBot[0]]), mat(0xa8a8a8));
scene.add(faceLeft);

/* winding hatching */
const hatchPts = [];
const NH = 120;
for (let k = 0; k < NH; k++) {
  const t = TH_A + (TH_B - TH_A) * (k + 0.5) / NH, c = Math.cos(t), s = Math.sin(t);
  hatchPts.push(new THREE.Vector3(R1 * c, H / 2 + 0.006, R1 * s), new THREE.Vector3(R2 * c, H / 2 + 0.006, R2 * s));
  hatchPts.push(new THREE.Vector3((R2 + 0.006) * c, H / 2, (R2 + 0.006) * s), new THREE.Vector3((R2 + 0.006) * c, -H / 2, (R2 + 0.006) * s));
  hatchPts.push(new THREE.Vector3((R1 - 0.006) * c, H / 2, (R1 - 0.006) * s), new THREE.Vector3((R1 - 0.006) * c, -H / 2, (R1 - 0.006) * s));
}
const hatch = new THREE.LineSegments(
  new THREE.BufferGeometry().setFromPoints(hatchPts),
  new THREE.LineBasicMaterial({ color: 0x4a4a4a, transparent: true, opacity: 0.85 }));
scene.add(hatch);

/* ── orange area element + accumulation ───────────────────────────────── */
const daMat = new THREE.MeshBasicMaterial({ color: 0xe8621a });
const daStrip = new THREE.Mesh(new THREE.BoxGeometry(DR, H, 0.03), daMat);
scene.add(daStrip);

const NACC = 48, accSlices = [];
const accGroup = new THREE.Group(); scene.add(accGroup);
for (let k = 0; k < NACC; k++) {
  const w = (R2 - R1) / NACC, xc = R1 + w * (k + 0.5);
  const m = new THREE.Mesh(new THREE.BoxGeometry(w * 0.96, H, 0.02),
    new THREE.MeshBasicMaterial({ color: 0xe8621a, transparent: true, opacity: 0.25 + 0.65 * (R1 / xc) }));
  m.position.set(xc, 0, 0.012);
  accGroup.add(m); accSlices.push({ mesh: m, xc });
}
accGroup.visible = false;

/* da leader */
const daLeader = mkLine(false);

/* ── dimension apparatus ──────────────────────────────────────────────── */
const yR2 = 2.25, yR1 = 1.80, yR = 1.35;
const dimLines = { R2: mkLine(false), R1: mkLine(false), r: mkLine(false), dr: mkLine(false) };
const heads = {};
['R2a', 'R2b', 'R1a', 'R1b', 'ra', 'rb', 'dr', 'ht', 'hb'].forEach(k => {
  heads[k] = arrowHead(0x000000, 0.055); scene.add(heads[k]);
});
setLine(dimLines.R2, [new THREE.Vector3(0, yR2, ZF), new THREE.Vector3(R2, yR2, ZF)]);
setLine(dimLines.R1, [new THREE.Vector3(0, yR1, ZF), new THREE.Vector3(R1, yR1, ZF)]);
aimHead(heads.R2a, new THREE.Vector3(0, yR2, ZF), new THREE.Vector3(-1, 0, 0));
aimHead(heads.R2b, new THREE.Vector3(R2, yR2, ZF), new THREE.Vector3(1, 0, 0));
aimHead(heads.R1a, new THREE.Vector3(0, yR1, ZF), new THREE.Vector3(-1, 0, 0));
aimHead(heads.R1b, new THREE.Vector3(R1, yR1, ZF), new THREE.Vector3(1, 0, 0));

/* dashed guides */
const axisLine = mkLine(true);
setLine(axisLine, [new THREE.Vector3(0, 2.55, ZF), new THREE.Vector3(0, -1.15, ZF)]);
const wallR1Line = mkLine(true), wallR2Line = mkLine(true);
setLine(wallR1Line, [new THREE.Vector3(R1, yR1 + 0.18, ZF), new THREE.Vector3(R1, H / 2 + 0.05, ZF)]);
setLine(wallR2Line, [new THREE.Vector3(R2, yR2 + 0.18, ZF), new THREE.Vector3(R2, H / 2 + 0.05, ZF)]);
const vR = mkLine(true), vRdr = mkLine(true);

/* h bracket */
const xh = R2 + 0.85;
const hBar = mkLine(false);
setLine(hBar, [new THREE.Vector3(xh, -H / 2, ZF), new THREE.Vector3(xh, H / 2, ZF)]);
aimHead(heads.ht, new THREE.Vector3(xh, H / 2, ZF), new THREE.Vector3(0, 1, 0));
aimHead(heads.hb, new THREE.Vector3(xh, -H / 2, ZF), new THREE.Vector3(0, -1, 0));
const hTop = mkLine(true), hBot = mkLine(true);
setLine(hTop, [new THREE.Vector3(R2 - 0.05, H / 2, ZF), new THREE.Vector3(xh + 0.18, H / 2, ZF)]);
setLine(hBot, [new THREE.Vector3(R2 - 0.05, -H / 2, ZF), new THREE.Vector3(xh + 0.18, -H / 2, ZF)]);

/* ── current + field arrows ───────────────────────────────────────────── */
function arcTube(fn, tA, tB, n, rad, color) {
  const pts = [];
  for (let i = 0; i <= n; i++) pts.push(fn(tA + (tB - tA) * i / n));
  const geo = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), n, rad, 8, false);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color })); scene.add(mesh);
  const dir = pts[n].clone().sub(pts[n - 1]);
  const head = arrowHead(color, rad * 3.2); scene.add(head);
  aimHead(head, pts[n].clone().addScaledVector(dir.clone().normalize(), rad * 3.2 * 1.2), dir);
  return { mesh, head, end: pts[n], start: pts[0] };
}
const uL = new THREE.Vector3(Math.cos(TH_A), 0, Math.sin(TH_A));
const nL = new THREE.Vector3(Math.sin(TH_A), 0, -Math.cos(TH_A));
const cCurl = uL.clone().multiplyScalar((R1 + R2) / 2).add(nL.clone().multiplyScalar(0.5)).add(new THREE.Vector3(0, 0.30, 0));
const curlI = arcTube(p => cCurl.clone().addScaledVector(nL, 0.30 * Math.cos(p)).addScaledVector(new THREE.Vector3(0, 1, 0), 0.30 * Math.sin(p)),
  D2R(115), D2R(-85), 40, 0.028, 0xd62b1f);

const RB = 2.55, yB = -H / 2 - 0.30;
const fieldFn = t => new THREE.Vector3(RB * Math.cos(t), yB, RB * Math.sin(t));
arcTube(fieldFn, D2R(155), D2R(103), 40, 0.032, 0x2e6fd6);
arcTube(fieldFn, D2R(92), D2R(46), 40, 0.032, 0x2e6fd6);

/* ── camera ───────────────────────────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 20, elevationDeg: 25, rollDeg: 0, heightFraction: 0.62 });

/* ── labels ───────────────────────────────────────────────────────────── */
const F = '15px';
addLabel('<i>R</i><sub>2</sub>', new THREE.Vector3(R2 * 0.48, yR2, ZF), { fontSize: F, offset: [0, -11] });
addLabel('<i>R</i><sub>1</sub>', new THREE.Vector3(R1 * 0.48, yR1, ZF), { fontSize: F, offset: [0, -11] });
const lblR = addLabel('<i>r</i>', new THREE.Vector3(1.35, yR, ZF), { fontSize: F, offset: [0, -11] });
const lblDr = addLabel('<i>dr</i>', new THREE.Vector3(2.8, yR, ZF), { fontSize: F, offset: [0, -11] });
addLabel('<i>h</i>', new THREE.Vector3(xh + 0.30, 0, ZF), { fontSize: F, offset: [10, 0] });
const lblDa = addLabel('<i>da</i>', new THREE.Vector3(3.0, 0.95, 0.3), { fontSize: F, offset: [14, 0] });
addLabel('<i>i</i>', curlI.start.clone().addScaledVector(nL, 0.30).add(new THREE.Vector3(0, 0.18, 0)),
  { fontSize: F, color: '#d62b1f', offset: [-8, -6] });
addLabel('<b>B</b>', fieldFn(D2R(128)).add(new THREE.Vector3(0, -0.26, 0)), { fontSize: '13px', color: '#2e6fd6' });

/* ── interactions on geometry ─────────────────────────────────────────── */
registerInteractive(daStrip, {
  title: 'Area element da = h·dr',
  tooltip: 'Area element da',
  body: 'A thin vertical strip of the cut face at radius r, width dr and height h. Because it is narrow, B = μ₀Ni/(2πr) is essentially constant over it, so dΦ = B·da = μ₀Nih dr/(2πr).'
});
registerInteractive(topFace, {
  title: 'Winding turns (N turns)',
  tooltip: 'The N winding turns',
  body: 'The fine radial hatching stands for the N closely wound turns that carry the current i around the toroid. Ampère\'s law with a circular loop of radius r inside the core gives B = μ₀Ni/(2πr).'
});
registerInteractive(inWall, {
  title: 'Inner radius R₁',
  tooltip: 'Inner wall, radius R₁',
  body: 'The central hole of radius R₁ = 2.0. Field lines circle inside the core between R₁ and R₂; outside the toroid the net enclosed current is zero, so B = 0.'
});
registerInteractive(faceRight, {
  title: 'Cross-section face',
  tooltip: 'Rectangular cross-section',
  body: 'The flat cut face is the rectangle (R₂−R₁)×h through which the flux is computed. B is perpendicular to this face everywhere, so Φ = ∫B da = μ₀Nih ln(R₂/R₁)/(2π).'
});

/* ── state / readouts ─────────────────────────────────────────────────── */
const MU0 = 4 * Math.PI * 1e-7, NT = 500, CUR = 1;
const PHI_TOT = MU0 * NT * CUR * H * Math.log(R2 / R1) / (2 * Math.PI);
const L_TOT = NT * PHI_TOT / CUR;

const slider = document.getElementById('radiusR');
const rOut = document.getElementById('rOut');
const readout = document.getElementById('readout');
const btnSingle = document.getElementById('btnSingle');
const btnAcc = document.getElementById('btnAcc');
let mode = 'single';
let rCur = 2.7, rTarget = 2.7;

function applyR(r) {
  const rs = Math.min(r, R2 - DR);            // strip stays inside the face
  daStrip.position.set(rs + DR / 2, 0, 0.018);
  // r dimension
  setLine(dimLines.r, [new THREE.Vector3(0, yR, ZF), new THREE.Vector3(r, yR, ZF)]);
  aimHead(heads.ra, new THREE.Vector3(0, yR, ZF), new THREE.Vector3(-1, 0, 0));
  aimHead(heads.rb, new THREE.Vector3(r, yR, ZF), new THREE.Vector3(1, 0, 0));
  lblR.pos.set(r * 0.48, yR, ZF);
  // dr marks
  setLine(dimLines.dr, [new THREE.Vector3(r + DR, yR, ZF), new THREE.Vector3(r + DR + 0.5, yR, ZF)]);
  aimHead(heads.dr, new THREE.Vector3(r + DR, yR, ZF), new THREE.Vector3(-1, 0, 0));
  lblDr.pos.set(r + DR + 0.62, yR, ZF);
  setLine(vR, [new THREE.Vector3(r, yR + 0.16, ZF), new THREE.Vector3(r, -H / 2 - 0.08, ZF)]);
  setLine(vRdr, [new THREE.Vector3(r + DR, yR + 0.16, ZF), new THREE.Vector3(r + DR, -H / 2 - 0.08, ZF)]);
  // da leader
  const p0 = new THREE.Vector3(rs + DR, H / 2 - 0.05, 0.06);
  const p2 = new THREE.Vector3(rs + 0.72, H / 2 + 0.42, 0.28);
  const p1 = new THREE.Vector3(rs + 0.18, H / 2 + 0.42, 0.20);
  setLine(daLeader, new THREE.QuadraticBezierCurve3(p0, p1, p2).getPoints(24));
  lblDa.pos.copy(p2);
  // accumulation
  for (const s of accSlices) s.mesh.visible = (mode === 'acc') && (s.xc <= r);
  // readout
  const B = MU0 * NT * CUR / (2 * Math.PI * r);
  const da = H * DR, dPhi = B * da;
  const phi = MU0 * NT * CUR * H * Math.log(r / R1) / (2 * Math.PI);
  let txt = `r      = ${r.toFixed(2)} m\n`;
  txt += `B(r)   = μ₀Ni/2πr = ${(B * 1e6).toFixed(1)} µT\n`;
  if (mode === 'single') {
    txt += `da     = h·dr = ${da.toFixed(4)} m²\n`;
    txt += `dΦ     = B·da = ${(dPhi * 1e6).toFixed(3)} µWb`;
  } else {
    txt += `Φ(R₁→r)= μ₀Nih·ln(r/R₁)/2π\n`;
    txt += `       = ${(phi * 1e6).toFixed(2)} µWb  (${(100 * phi / PHI_TOT).toFixed(0)}%)\n`;
    txt += `Φ_tot  = ${(PHI_TOT * 1e6).toFixed(2)} µWb\n`;
    txt += `L = NΦ/i = ${(L_TOT * 1e3).toFixed(1)} mH`;
  }
  readout.textContent = txt;
  rOut.textContent = r.toFixed(2);
}
function setMode(m) {
  mode = m;
  accGroup.visible = (m === 'acc');
  btnSingle.classList.toggle('active', m === 'single');
  btnAcc.classList.toggle('active', m === 'acc');
  applyR(rCur);
}
slider.addEventListener('input', () => { rCur = rTarget = parseFloat(slider.value); applyR(rCur); });
btnSingle.addEventListener('click', () => setMode('single'));
btnAcc.addEventListener('click', () => setMode('acc'));

/* ── guided tour ──────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'The cut toroid', n: 'A toroid of rectangular cross-section is cut open so you face the flat end. The winding hatching runs radially over the top; R₁ and R₂ are the inner and outer radii and h is the height of the face.', r: 2.0, m: 'single' },
  { t: 'One area element da', n: 'At radius r a thin orange strip of width dr and height h is the area element da = h·dr. The field there is B = μ₀Ni/(2πr), uniform across this narrow strip.', r: 2.2, m: 'single' },
  { t: 'Slide the strip outward', n: 'Drag r toward R₂ and watch B shrink as 1/r: the same-sized strip carries less flux the farther out it sits. That is why the flux is not simply B times the whole face area.', r: 3.1, m: 'single' },
  { t: 'Sum the strips', n: 'In accumulate mode the swept region from R₁ out to r fills in and Φ grows as ∫B h dr. At r = R₂ the whole face is covered: Φ = μ₀Nih ln(R₂/R₁)/(2π), hence L = NΦ/i.', r: 3.2, m: 'acc' }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');
function goToStep(k) {
  stepIdx = (k + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = `${stepIdx + 1}/${STEPS.length} · ${s.t}`;
  stepText.textContent = s.n;
  setMode(s.m);
  rTarget = s.r;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* tween loop (independent of the scaffold render loop) */
(function tick() {
  requestAnimationFrame(tick);
  if (Math.abs(rCur - rTarget) > 1e-4) {
    rCur += (rTarget - rCur) * 0.10;
    if (Math.abs(rCur - rTarget) <= 1e-4) rCur = rTarget;
    slider.value = rCur.toFixed(2);
    applyR(rCur);
  }
})();

setMode('single');
goToStep(0);
rCur = 2.7; rTarget = 2.7; slider.value = '2.7'; applyR(2.7);
stepTitle.textContent = `1/${STEPS.length} · ${STEPS[0].t}`;
stepText.textContent = STEPS[0].n;
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

