<div style="font-size:10px;color:#666;line-height:1.35">Drag to orbit: the orange strip <i>da</i> lies in the flat cut face, perpendicular to <b>B</b>. Click the body for explanations.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec ─────────────────────────────────────────────────────────
   toroid = HALF ring (t = 180°→360°), front half removed -> arch, both flat
   cut faces (x = ±R1..±R2, z = 0) face the camera at +Z.
   top annulus        -> quadStrip(innerTop,outerTop)        MeshLambert #b3b3b3
   bottom annulus     -> quadStrip(innerBot,outerBot)        MeshLambert #a8a8a8
   outer wall (R2)    -> quadStrip(outerTop,outerBot)        MeshLambert #8f8f8f
   inner hole wall    -> quadStrip(innerTop,innerBot)        MeshLambert #5a5a5a
   right cut face     -> quad at t=360°                      MeshLambert #c4c4c4
   left cut face      -> quad at t=180°                      MeshLambert #bdbdbd
   face outlines      -> LineLoop x2                         #3a3a3a
   winding hatching   -> LineSegments 120 radial + wall verticals #4a4a4a
   dashed axis line   -> Line dashed black at x=0, z=ZF
   R2/R1/r dim rows   -> Line + ConeGeometry heads (both ends), black
   dr dim             -> 2 short lines + inward cones + 2 dashed verticals
   h bracket          -> vertical Line + 2 cones + 2 dashed horizontals
   da strip           -> BoxGeometry(0.08,h,0.03) solid      #e8621a
   accumulate region  -> 48 thin boxes, opacity ~ 1/r        #e8621a
   da leader          -> QuadraticBezier Line black
   current i          -> TubeGeometry arc + cone head        #d62b1f (left end)
   B field arrows(x2) -> TubeGeometry arcs + cone heads      #2e6fd6 (lower body)
──────────────────────────────────────────────────────────────────────────*/

const D2R = THREE.MathUtils.degToRad;
const R1 = 2.0, R2 = 3.2, H = 0.8, DR = 0.08;
const TH_A = Math.PI, TH_B = 2 * Math.PI;      // kept material = back half
const NSEG = 180;
const ZF = 0.06;                               // annotation plane, proud of cut face

/* ── lighting ─────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0x909090, 1.9));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.55); keyLight.position.set(-5, 6, 6); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.55); fillLight.position.set(5, 2, 4); scene.add(fillLight);

/* ── helpers ──────────────────────────────────────────────────────────── */
function quadStrip(A, B) {
  const pos = [], idx = [];
  for (let i = 0; i < A.length; i++) { pos.push(A[i].x, A[i].y, A[i].z, B[i].x, B[i].y, B[i].z); }
  for (let i = 0; i < A.length - 1; i++) { const a = 2 * i, b = 2 * i + 1, c = 2 * i + 2, e = 2 * i + 3; idx.push(a, b, e, a, e, c); }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx); g.computeVertexNormals(); return g;
}
function mat(hex) { return new THREE.MeshLambertMaterial({ color: hex, side: THREE.DoubleSide }); }
function ringPts(rad, y) {
  const a = [];
  for (let i = 0; i <= NSEG; i++) { const t = TH_A + (TH_B - TH_A) * i / NSEG; a.push(new THREE.Vector3(rad * Math.cos(t), y, rad * Math.sin(t))); }
  return a;
}
function arrowHead(color, size) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(size, size * 2.5, 14), new THREE.MeshBasicMaterial({ color }));
  m.userData.size = size; m.renderOrder = 4; return m;
}
function aimHead(mesh, tip, dir) {
  const dd = dir.clone().normalize();
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dd);
  mesh.position.copy(tip).addScaledVector(dd, -mesh.userData.size * 1.25);
}
function mkLine(dashed, color) {
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: color ?? 0x000000, dashSize: 0.11, gapSize: 0.075 })
    : new THREE.LineBasicMaterial({ color: color ?? 0x000000 });
  const l = new THREE.Line(new THREE.BufferGeometry(), m);
  l.renderOrder = 3; scene.add(l); return l;
}
function setLine(l, pts) {
  l.geometry.dispose();
  l.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (l.material.isLineDashedMaterial) l.computeLineDistances();
}

/* ── toroid body (half ring / arch) ───────────────────────────────────── */
const innerTop = ringPts(R1, H / 2), outerTop = ringPts(R2, H / 2);
const innerBot = ringPts(R1, -H / 2), outerBot = ringPts(R2, -H / 2);

const topFace = new THREE.Mesh(quadStrip(innerTop, outerTop), mat(0xb3b3b3)); scene.add(topFace);
