function arcTube(fn, tA, tB, n, rad, color) {
  const pts = [];
  for (let i = 0; i <= n; i++) pts.push(fn(tA + (tB - tA) * i / n));
  const geo = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), n, rad, 8, false);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color })); scene.add(mesh);
  const dir = pts[n].clone().sub(pts[n - 1]);
  const head = arrowHead(color, rad * 3.1); scene.add(head);
  aimHead(head, pts[n].clone().addScaledVector(dir.clone().normalize(), rad * 3.0), dir);
  return { mesh, head, end: pts[n], start: pts[0] };
}
