  daStrip.position.set(rs + DR / 2, 0, 0.022);

  /* r dimension row */
  setLine(dimLines.r, [new THREE.Vector3(0, yR, ZF), new THREE.Vector3(r, yR, ZF)]);
  aimHead(heads.ra, new THREE.Vector3(0, yR, ZF), new THREE.Vector3(-1, 0, 0));
  aimHead(heads.rb, new THREE.Vector3(r, yR, ZF), new THREE.Vector3(1, 0, 0));
  lblR.pos.set(r * 0.5, yR, ZF);

  /* dr: inward-pointing short arrows either side of the dr gap */
  setLine(dimLines.drL, [new THREE.Vector3(r - 0.55, yR, ZF), new THREE.Vector3(r, yR, ZF)]);
  setLine(dimLines.drR, [new THREE.Vector3(r + DR + 0.80, yR, ZF), new THREE.Vector3(r + DR, yR, ZF)]);
  aimHead(heads.drL, new THREE.Vector3(r, yR, ZF), new THREE.Vector3(1, 0, 0));
  aimHead(heads.drR, new THREE.Vector3(r + DR, yR, ZF), new THREE.Vector3(-1, 0, 0));
  lblDr.pos.set(r + DR + 0.95, yR, ZF);

  /* dashed verticals bounding the strip */
  setLine(vR, [new THREE.Vector3(r, yR + 0.20, ZF), new THREE.Vector3(r, -H / 2 - 0.16, ZF)]);
  setLine(vRdr, [new THREE.Vector3(r + DR, yR + 0.20, ZF), new THREE.Vector3(r + DR, -H / 2 - 0.16, ZF)]);

  /* da leader */
  const p0 = new THREE.Vector3(rs + DR, 0.14, 0.07);
  const p1 = new THREE.Vector3(rs + DR + 0.16, 0.34, 0.09);
  const p2 = new THREE.Vector3(rs + DR + 0.34, 0.30, 0.10);
  setLine(daLeader, new THREE.QuadraticBezierCurve3(p0, p1, p2).getPoints(22));
  lblDa.pos.copy(p2);

  for (const s of accSlices) s.mesh.visible = (mode === 'acc') && (s.xc <= r);

  const B = MU0 * NT * CUR / (2 * Math.PI * r);
  const da = H * DR, dPhi = B * da;
  const phi = MU0 * NT * CUR * H * Math.log(r / R1) / (2 * Math.PI);
  let txt = `r      = ${r.toFixed(2)} m\n`;
  txt += `B(r)   = μ₀Ni/2πr = ${(B * 1e6).toFixed(1)} µT\n`;
  if (mode === 'single') {
    txt += `da     = h·dr = ${da.toFixed(4)} m²\n`;
    txt += `dΦ     = B·da = ${(dPhi * 1e6).toFixed(3)} µWb`;
  } else {
    txt += `Φ(R₁→r)= μ₀Nih·ln(r/R₁)/2π\n`;
    txt += `       = ${(phi * 1e6).toFixed(2)} µWb  (${(100 * phi / PHI_TOT).toFixed(0)}%)\n`;
    txt += `Φ_tot  = ${(PHI_TOT * 1e6).toFixed(2)} µWb\n`;
    txt += `L = NΦ/i = ${(L_TOT * 1e3).toFixed(1)} mH`;
  }
  readout.textContent = txt;
  rOut.textContent = r.toFixed(2);
}
function setMode(m) {
