Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:bold;font-size:13px">Toroid — flux through the cut face</div>
<label><span>radius <i>r</i> = <span id="rOut">2.70</span> m</span>
  <input id="radiusR" type="range" min="2" max="3.2" step="0.02" value="2.7">
</label>
<div style="margin-top:2px">view</div>
<div style="display:flex;gap:4px;flex-wrap:wrap">
  <button id="btnSingle" class="active">single slice da</button>
  <button id="btnAcc">accumulate R₁ → r</button>
</div>
<div id="readout" style="font-family:ui-monospace,Consolas,monospace;font-size:11px;line-height:1.55;background:#f2f4f7;border:1px solid #dcdfe3;border-radius:4px;padding:6px 8px;white-space:pre-wrap"></div>
<div style="font-weight:bold;margin-top:4px">Guided tour</div>
<div style="display:flex;gap:4px">
  <button id="btnPrev">◀ Prev</button><button id="btnNext">Next ▶</button>
</div>
<div id="stepTitle" style="font-weight:bold"></div>
<div id="stepText" style="line-height:1.4"></div>
<div style="font-size:10px;color:#666;line-height:1.35">Red arrow <i>i</i> = current in the windings; blue arrows <b>B</b> = circulating field. Drag to orbit: the orange strip <i>da</i> lies in the flat cut face, perpendicular to <b>B</b>. Click any part for an explanation.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec ─────────────────────────────────────────────────────────
   Whole figure lives in `root`, yawed +70° so the scaffold camera
   (azimuth 20°, elev 25°) sees the arch front-on with the right cut face
   pointing at the viewer, exactly as in the source plate.
   toroid = HALF ring (t = 180°→360°); front half removed -> arch.
   top annulus        -> quadStrip(innerTop,outerTop)     MeshLambert #b3b3b3
   bottom annulus     -> quadStrip(innerBot,outerBot)     MeshLambert #a8a8a8
   outer wall (R2)    -> quadStrip(outerTop,outerBot)     MeshLambert #8f8f8f
   inner hole wall    -> quadStrip(innerTop,innerBot)     MeshLambert #585858
   right cut face     -> quad at t=360°                   MeshLambert #c6c6c6
   left cut face      -> quad at t=180°                   MeshLambert #bdbdbd
   face outlines      -> LineLoop x2                      #3a3a3a
   winding hatching   -> LineSegments 120 radial + wall verticals #4a4a4a
   dashed axis line   -> Line dashed black at x=0, z=ZF
   R2/R1/r dim rows   -> Line + ConeGeometry heads, black (tight stack)
   dr                 -> r's right head + one inward head + tail, 2 dashes
   h bracket          -> vertical Line + 2 cones + 2 dashed horizontals
   da strip           -> BoxGeometry(0.08,h,0.02) flush in face  #e8621a
   accumulate region  -> 48 thin boxes, opacity ~ 1/r            #e8621a
   da leader          -> QuadraticBezier Line  #222222
   current i          -> TubeGeometry arc + cone head  #d62b1f (left end)
   B field arrows(x2) -> TubeGeometry arcs + cone heads #2e6fd6 (front, below)
──────────────────────────────────────────────────────────────────────────*/

const D2R = THREE.MathUtils.degToRad;
const R1 = 2.0, R2 = 3.2, H = 0.8, DR = 0.08;
const TH_A = Math.PI, TH_B = 2 * Math.PI;      // kept material = back half
const NSEG = 180;
const ZF = 0.06;                               // annotation plane, proud of cut face
const YAW = 70;                                // scene yaw so azimuth 20° reads front-on

const root = new THREE.Group();
root.rotation.y = D2R(YAW);
scene.add(root);
const ROT = new THREE.Matrix4().makeRotationY(D2R(YAW));
const W = (x, y, z) => new THREE.Vector3(x, y, z).applyMatrix4(ROT);
const WV = v => v.clone().applyMatrix4(ROT);

/* ── lighting (inside root -> same shading as a front-on key light) ───── */
root.add(new THREE.HemisphereLight(0xffffff, 0x909090, 1.9));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.55); keyLight.position.set(-5, 6, 6); root.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.55); fillLight.position.set(5, 2, 4); root.add(fillLight);

/* ── helpers ──────────────────────────────────────────────────────────── */
function quadStrip(A, B) {
  const pos = [], idx = [];
  for (let i = 0; i < A.length; i++) { pos.push(A[i].x, A[i].y, A[i].z, B[i].x, B[i].y, B[i].z); }
  for (let i = 0; i < A.length - 1; i++) { const a = 2 * i, b = 2 * i + 1, c = 2 * i + 2, e = 2 * i + 3; idx.push(a, b, e, a, e, c); }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx); g.computeVertexNormals(); return g;
}
function mat(hex) { return new THREE.MeshLambertMaterial({ color: hex, side: THREE.DoubleSide }); }
function ringPts(rad, y) {
  const a = [];
  for (let i = 0; i <= NSEG; i++) { const t = TH_A + (TH_B - TH_A) * i / NSEG; a.push(new THREE.Vector3(rad * Math.cos(t), y, rad * Math.sin(t))); }
  return a;
}
function arrowHead(color, size) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(size, size * 2.5, 14), new THREE.MeshBasicMaterial({ color }));
  m.userData.size = size; m.renderOrder = 4; return m;
}
function aimHead(mesh, tip, dir) {
  const dd = dir.clone().normalize();
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dd);
  mesh.position.copy(tip).addScaledVector(dd, -mesh.userData.size * 1.25);
}
function mkLine(dashed, color) {
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: color ?? 0x000000, dashSize: 0.10, gapSize: 0.07 })
    : new THREE.LineBasicMaterial({ color: color ?? 0x000000 });
  const l = new THREE.Line(new THREE.BufferGeometry(), m);
  l.renderOrder = 3; root.add(l); return l;
}
function setLine(l, pts) {
  l.geometry.dispose();
  l.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (l.material.isLineDashedMaterial) l.computeLineDistances();
}

/* ── toroid body (half ring / arch) ───────────────────────────────────── */
const innerTop = ringPts(R1, H / 2), outerTop = ringPts(R2, H / 2);
const innerBot = ringPts(R1, -H / 2), outerBot = ringPts(R2, -H / 2);

const topFace = new THREE.Mesh(quadStrip(innerTop, outerTop), mat(0xb3b3b3)); root.add(topFace);
const botFace = new THREE.Mesh(quadStrip(innerBot, outerBot), mat(0xa8a8a8)); root.add(botFace);
const outWall = new THREE.Mesh(quadStrip(outerTop, outerBot), mat(0x8f8f8f)); root.add(outWall);
const inWall = new THREE.Mesh(quadStrip(innerTop, innerBot), mat(0x585858)); root.add(inWall);

const last = NSEG;
const faceRight = new THREE.Mesh(
  quadStrip([innerTop[last], outerTop[last]], [innerBot[last], outerBot[last]]), mat(0xc6c6c6));
root.add(faceRight);
const faceLeft = new THREE.Mesh(
  quadStrip([innerTop[0], outerTop[0]], [innerBot[0], outerBot[0]]), mat(0xbdbdbd));
root.add(faceLeft);

/* cut-face outlines */
function faceOutline(sx) {
  const p = [
    new THREE.Vector3(sx * R1, H / 2, 0), new THREE.Vector3(sx * R2, H / 2, 0),
    new THREE.Vector3(sx * R2, -H / 2, 0), new THREE.Vector3(sx * R1, -H / 2, 0),
    new THREE.Vector3(sx * R1, H / 2, 0)];
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(p),
    new THREE.LineBasicMaterial({ color: 0x3a3a3a }));
  l.position.z = 0.004; root.add(l);
}
faceOutline(1); faceOutline(-1);

/* winding hatching: radial on top + verticals on both walls */
const hatchPts = [];
const NH = 120;
for (let k = 0; k < NH; k++) {
  const t = TH_A + (TH_B - TH_A) * (k + 0.5) / NH, c = Math.cos(t), s = Math.sin(t);
  hatchPts.push(new THREE.Vector3(R1 * c, H / 2 + 0.007, R1 * s), new THREE.Vector3(R2 * c, H / 2 + 0.007, R2 * s));
  hatchPts.push(new THREE.Vector3((R2 + 0.007) * c, H / 2, (R2 + 0.007) * s), new THREE.Vector3((R2 + 0.007) * c, -H / 2, (R2 + 0.007) * s));
  hatchPts.push(new THREE.Vector3((R1 - 0.007) * c, H / 2, (R1 - 0.007) * s), new THREE.Vector3((R1 - 0.007) * c, -H / 2, (R1 - 0.007) * s));
}
const hatch = new THREE.LineSegments(
  new THREE.BufferGeometry().setFromPoints(hatchPts),
  new THREE.LineBasicMaterial({ color: 0x4a4a4a, transparent: true, opacity: 0.85 }));
root.add(hatch);

/* ── orange area element + accumulation (flush in the RIGHT cut face) ─── */
const daStrip = new THREE.Mesh(new THREE.BoxGeometry(DR, H, 0.02),
  new THREE.MeshBasicMaterial({ color: 0xe8621a }));
root.add(daStrip);

const NACC = 48, accSlices = [];
const accGroup = new THREE.Group(); root.add(accGroup);
for (let k = 0; k < NACC; k++) {
  const w = (R2 - R1) / NACC, xc = R1 + w * (k + 0.5);
  const m = new THREE.Mesh(new THREE.BoxGeometry(w * 0.96, H, 0.016),
    new THREE.MeshBasicMaterial({ color: 0xe8621a, transparent: true, opacity: 0.22 + 0.68 * (R1 / xc) }));
  m.position.set(xc, 0, 0.008);
  accGroup.add(m); accSlices.push({ mesh: m, xc });
}
accGroup.visible = false;

const daLeader = mkLine(false, 0x222222);

/* ── dimension apparatus (all in the z = ZF plane, tight above the arch) ─ */
const yR2 = 2.92, yR1 = 2.56, yR = 2.20;
const dimLines = { R2: mkLine(false), R1: mkLine(false), r: mkLine(false), drTail: mkLine(false) };
const heads = {};
['R2a', 'R2b', 'R1a', 'R1b', 'ra', 'rb', 'drR', 'ht', 'hb'].forEach(k => {
  heads[k] = arrowHead(0x000000, 0.052); root.add(heads[k]);
});
setLine(dimLines.R2, [new THREE.Vector3(0, yR2, ZF), new THREE.Vector3(R2, yR2, ZF)]);
setLine(dimLines.R1, [new THREE.Vector3(0, yR1, ZF), new THREE.Vector3(R1, yR1, ZF)]);
aimHead(heads.R2a, new THREE.Vector3(0, yR2, ZF), new THREE.Vector3(-1, 0, 0));
aimHead(heads.R2b, new THREE.Vector3(R2, yR2, ZF), new THREE.Vector3(1, 0, 0));
aimHead(heads.R1a, new THREE.Vector3(0, yR1, ZF), new THREE.Vector3(-1, 0, 0));
aimHead(heads.R1b, new THREE.Vector3(R1, yR1, ZF), new THREE.Vector3(1, 0, 0));

/* dashed guides */
const axisLine = mkLine(true);
setLine(axisLine, [new THREE.Vector3(0, 3.12, ZF), new THREE.Vector3(0, -1.15, ZF)]);
const wallR1Line = mkLine(true), wallR2Line = mkLine(true);
setLine(wallR2Line, [new THREE.Vector3(R2, yR2 + 0.16, ZF), new THREE.Vector3(R2, H / 2 + 0.02, ZF)]);
setLine(wallR1Line, [new THREE.Vector3(R1, yR1 + 0.16, ZF), new THREE.Vector3(R1, H / 2 + 0.02, ZF)]);
const vR = mkLine(true), vRdr = mkLine(true);   // the ONLY two verticals bounding the strip

/* h bracket at the far right of the front face */
const xh = R2 + 0.55;
const hBar = mkLine(false);
setLine(hBar, [new THREE.Vector3(xh, -H / 2, ZF), new THREE.Vector3(xh, H / 2, ZF)]);
aimHead(heads.ht, new THREE.Vector3(xh, H / 2, ZF), new THREE.Vector3(0, 1, 0));
aimHead(heads.hb, new THREE.Vector3(xh, -H / 2, ZF), new THREE.Vector3(0, -1, 0));
const hTop = mkLine(true), hBot = mkLine(true);
setLine(hTop, [new THREE.Vector3(R2 - 0.05, H / 2, ZF), new THREE.Vector3(xh + 0.15, H / 2, ZF)]);
setLine(hBot, [new THREE.Vector3(R2 - 0.05, -H / 2, ZF), new THREE.Vector3(xh + 0.15, -H / 2, ZF)]);

/* ── current + field arrows ───────────────────────────────────────────── */
function arcTube(fn, tA, tB, n, rad, color) {
  const pts = [];
  for (let i = 0; i <= n; i++) pts.push(fn(tA + (tB - tA) * i / n));
  const geo = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), n, rad, 8, false);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color })); root.add(mesh);
  const dir = pts[n].clone().sub(pts[n - 1]);
  const head = arrowHead(color, rad * 3.1); root.add(head);
  aimHead(head, pts[n].clone().addScaledVector(dir.clone().normalize(), rad * 3.0), dir);
  return { mesh, head, end: pts[n], start: pts[0] };
}
/* current i: curls over the LEFT end of the arch, kept inside the frame */
const cCurl = new THREE.Vector3(-(R2 - 0.12), 0.46, 0.10);
const curlI = arcTube(p => cCurl.clone().add(new THREE.Vector3(0.30 * Math.cos(p), 0.30 * Math.sin(p), 0)),
  D2R(-8), D2R(200), 40, 0.028, 0xd62b1f);

/* B field: two arcs in the OPEN front half, below the body -> always visible */
const RB = (R1 + R2) / 2, yB = -H / 2 - 0.18;
const fieldFn = t => new THREE.Vector3(RB * Math.cos(t), yB, RB * Math.sin(t));
const arcBL = arcTube(fieldFn, D2R(176), D2R(139), 40, 0.034, 0x2e6fd6);
const arcBR = arcTube(fieldFn, D2R(41), D2R(4), 40, 0.034, 0x2e6fd6);

/* ── camera (perspective, pose from the plan; scene pre-yawed) ────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 20, elevationDeg: 25, rollDeg: 0, heightFraction: 0.8 });

/* ── labels ───────────────────────────────────────────────────────────── */
const F = '16px';
addLabel('<i>R</i><sub>2</sub>', W(R2 * 0.5, yR2, ZF), { fontSize: F, offset: [0, -12] });
addLabel('<i>R</i><sub>1</sub>', W(R1 * 0.5, yR1, ZF), { fontSize: F, offset: [0, -12] });
const lblR = addLabel('<i>r</i>', W(1.1, yR, ZF), { fontSize: F, offset: [0, -12] });
const lblDr = addLabel('<i>dr</i>', W(3.0, yR, ZF), { fontSize: F, offset: [16, -3] });
addLabel('<i>h</i>', W(xh - 0.26, 0, ZF), { fontSize: F, offset: [-3, 0] });
const lblDa = addLabel('<i>da</i>', W(3.0, 0.30, 0.1), { fontSize: F, offset: [14, -4] });
addLabel('<i>i</i>', WV(cCurl).add(WV(new THREE.Vector3(-0.34, 0.26, 0))), { fontSize: '17px', color: '#d62b1f', bold: true });
addLabel('<b>B</b>', WV(arcBL.end).add(WV(new THREE.Vector3(0.02, -0.14, 0.10))), { fontSize: '15px', color: '#2e6fd6', offset: [0, 13] });
addLabel('<b>B</b>', WV(arcBR.end).add(WV(new THREE.Vector3(0.16, -0.12, 0.06))), { fontSize: '15px', color: '#2e6fd6', offset: [10, 10] });

/* ── click / hover explanations ───────────────────────────────────────── */
registerInteractive(daStrip, {
  title: 'Area element da = h·dr',
  tooltip: 'Area element da',
  body: 'A thin vertical strip of the cut face at radius r, width dr and height h. Because it is narrow, B = μ₀Ni/(2πr) is essentially constant over it, so dΦ = B·da = μ₀Nih dr/(2πr).'
});
registerInteractive(topFace, {
  title: 'Winding turns (N turns)',
  tooltip: 'The N winding turns',
  body: 'The fine radial hatching stands for the N closely wound turns carrying current i around the toroid. Ampère\'s law on a circular loop of radius r inside the core gives B = μ₀Ni/(2πr).'
});
registerInteractive(inWall, {
  title: 'Inner radius R₁',
  tooltip: 'Inner wall, radius R₁',
  body: 'The central hole of radius R₁ = 2.0 m. Field lines circle inside the core between R₁ and R₂; outside the toroid the net enclosed current is zero, so B = 0.'
});
registerInteractive(faceRight, {
  title: 'Cross-section face',
  tooltip: 'Rectangular cross-section (R₂−R₁)×h',
  body: 'The flat cut face is the rectangle (R₂−R₁)×h through which the flux of one turn is computed. B is perpendicular to this face everywhere, so Φ = ∫B da = μ₀Nih ln(R₂/R₁)/(2π) and L = NΦ/i.'
});
registerInteractive(outWall, {
  title: 'Outer radius R₂',
  tooltip: 'Outer wall, radius R₂',
  body: 'The outer wall at R₂ = 3.2 m. Integrating the strips from R₁ to R₂ produces the logarithm ln(R₂/R₁) in the flux and in the self-inductance.'
});
registerInteractive(curlI.mesh, {
  title: 'Current i in the windings',
  tooltip: 'Current i (red)',
  body: 'The red arrow shows the current i entering the winding at the cut end. Each of the N turns carries this same current, and it is this current that Ampère\'s loop encloses N times.'
});
[arcBL.mesh, arcBR.mesh].forEach(m => registerInteractive(m, {
  title: 'Circulating field B',
  tooltip: 'Field direction B (blue)',
  body: 'The blue arrows follow the circulating magnetic field inside the core, set by the right-hand rule from the current i. B runs along the ring, so it pierces the flat cut face at right angles — which is why the flux through da is the simple product B·da.'
}));

/* ── state / readouts ─────────────────────────────────────────────────── */
const MU0 = 4 * Math.PI * 1e-7, NT = 500, CUR = 1;
const PHI_TOT = MU0 * NT * CUR * H * Math.log(R2 / R1) / (2 * Math.PI);
const L_TOT = NT * PHI_TOT / CUR;

const slider = document.getElementById('radiusR');
const rOut = document.getElementById('rOut');
const readout = document.getElementById('readout');
const btnSingle = document.getElementById('btnSingle');
const btnAcc = document.getElementById('btnAcc');
let mode = 'single';
let rCur = 2.7, rTarget = 2.7;

function applyR(r) {
  const rs = Math.min(r, R2 - DR);
  daStrip.position.set(rs + DR / 2, 0, 0.011);

  /* r dimension row */
  setLine(dimLines.r, [new THREE.Vector3(0, yR, ZF), new THREE.Vector3(r, yR, ZF)]);
  aimHead(heads.ra, new THREE.Vector3(0, yR, ZF), new THREE.Vector3(-1, 0, 0));
  aimHead(heads.rb, new THREE.Vector3(r, yR, ZF), new THREE.Vector3(1, 0, 0));
  lblR.pos.copy(W(r * 0.5, yR, ZF));

  /* dr: r's right head + one inward head at r+dr with a short tail */
  setLine(dimLines.drTail, [new THREE.Vector3(r + DR, yR, ZF), new THREE.Vector3(r + DR + 0.55, yR, ZF)]);
  aimHead(heads.drR, new THREE.Vector3(r + DR, yR, ZF), new THREE.Vector3(-1, 0, 0));
  lblDr.pos.copy(W(r + DR + 0.55, yR, ZF));

  /* the only two dashed verticals: they bound the strip */
  setLine(vR, [new THREE.Vector3(r, yR + 0.24, ZF), new THREE.Vector3(r, -H / 2 - 0.22, ZF)]);
  setLine(vRdr, [new THREE.Vector3(r + DR, yR + 0.24, ZF), new THREE.Vector3(r + DR, -H / 2 - 0.22, ZF)]);

  /* da leader (dark, short) */
  const p0 = new THREE.Vector3(rs + DR, 0.16, 0.05);
  const p1 = new THREE.Vector3(rs + DR + 0.18, 0.36, 0.07);
  const p2 = new THREE.Vector3(rs + DR + 0.36, 0.31, 0.08);
  setLine(daLeader, new THREE.QuadraticBezierCurve3(p0, p1, p2).getPoints(22));
  lblDa.pos.copy(WV(p2));

  for (const s of accSlices) s.mesh.visible = (mode === 'acc') && (s.xc <= r);

  const B = MU0 * NT * CUR / (2 * Math.PI * r);
  const da = H * DR, dPhi = B * da;
  const phi = MU0 * NT * CUR * H * Math.log(r / R1) / (2 * Math.PI);
  let txt = `r      = ${r.toFixed(2)} m\n`;
  txt += `B(r)   = μ₀Ni/2πr = ${(B * 1e6).toFixed(1)} µT\n`;
  if (mode === 'single') {
    txt += `da     = h·dr = ${da.toFixed(4)} m²\n`;
    txt += `dΦ     = B·da = ${(dPhi * 1e6).toFixed(3)} µWb`;
  } else {
    txt += `Φ(R₁→r)= μ₀Nih·ln(r/R₁)/2π\n`;
    txt += `       = ${(phi * 1e6).toFixed(2)} µWb  (${(100 * phi / PHI_TOT).toFixed(0)}%)\n`;
    txt += `Φ_tot  = ${(PHI_TOT * 1e6).toFixed(2)} µWb\n`;
    txt += `L = NΦ/i = ${(L_TOT * 1e3).toFixed(1)} mH`;
  }
  readout.textContent = txt;
  rOut.textContent = r.toFixed(2);
}
function setMode(m) {
  mode = m;
  accGroup.visible = (m === 'acc');
  btnSingle.classList.toggle('active', m === 'single');
  btnAcc.classList.toggle('active', m === 'acc');
  applyR(rCur);
}
slider.addEventListener('input', () => { rCur = rTarget = parseFloat(slider.value); applyR(rCur); });
btnSingle.addEventListener('click', () => setMode('single'));
btnAcc.addEventListener('click', () => setMode('acc'));

/* ── guided tour ──────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'The cut toroid', n: 'A toroid of rectangular cross-section is cut open so you face the flat end. The hatching on the top is the N winding turns; R₁ and R₂ are the inner and outer radii and h is the height of the face.', r: 2.0, m: 'single' },
  { t: 'One area element da', n: 'At radius r a thin orange strip of width dr and height h is the area element da = h·dr. The field there is B = μ₀Ni/(2πr), essentially uniform across this narrow strip.', r: 2.2, m: 'single' },
  { t: 'Slide the strip outward', n: 'Drag r toward R₂ and watch B shrink as 1/r: the same-sized strip carries less flux the farther out it sits. That is why the flux is not simply B times the whole face area.', r: 3.1, m: 'single' },
  { t: 'Sum the strips', n: 'In accumulate mode the swept region from R₁ out to r fills in and Φ grows as ∫B h dr. At r = R₂ the whole face is covered: Φ = μ₀Nih ln(R₂/R₁)/(2π), hence L = NΦ/i.', r: 3.2, m: 'acc' }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');
function goToStep(k) {
  stepIdx = (k + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = `${stepIdx + 1}/${STEPS.length} · ${s.t}`;
  stepText.textContent = s.n;
  setMode(s.m);
  rTarget = s.r;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* tween loop */
(function tick() {
  requestAnimationFrame(tick);
  if (Math.abs(rCur - rTarget) > 1e-4) {
    rCur += (rTarget - rCur) * 0.10;
    if (Math.abs(rCur - rTarget) <= 1e-4) rCur = rTarget;
    slider.value = rCur.toFixed(2);
    applyR(rCur);
  }
})();

